export const SCRIPT_EXAMPLE = {"source":{"name":"jobs","kind":"script","runner":"python3","why":"Jobs per state from the shop's job queue tool (queuectl, with a read-only token)","secrets":["QUEUE_READ_TOKEN"],"code":"import json, subprocess, sys\nargs = json.load(sys.stdin)\nout = subprocess.run([\"queuectl\", \"jobs\", \"--state\", args.get(\"state\", \"open\"), \"--json\"], capture_output=True, text=True, check=True).stdout\nprint(json.dumps({\"rows\": json.loads(out)}))"},"program":"root = Dashboard([filters, main])\n$state = \"open\"\nfilters = FilterBar([ChipFilter($state, [{value: \"open\", label: \"Open\"}, {value: \"failed\", label: \"Failed\"}])])\njobs = Query(\"jobs\", {state: $state}, {rows: []}, 60)\nmain = Section(\"Jobs\", [Row([Card(\"Jobs\", [Table([Column(\"Job\", jobs.rows.id, \"primary\"), Column(\"State\", jobs.rows.state), Column(\"Age\", jobs.rows.age)])], \"full\")]), Freshness(\"jobs\")])"};
export const SIGNATURES: Record<string, string> = {
  "Dashboard": "Dashboard(children: (FilterBar | Section)[]) — The root.",
  "FilterBar": "FilterBar(filters: (PeriodPicker | DateRangeFilter | ChipFilter | SelectFilter | MultiSelectFilter | CompareToggle)[]) — Sticky row of dashboard-wide filters, right after the header.",
  "PeriodPicker": "PeriodPicker(value: $binding<string>, options: {value: string, label?: string}[]) — Segmented control for a few date presets, e.g. [{value: \"7d\", label: \"7D\"}, {value: \"30d\", label: \"30D\"}]. value takes the $variable that holds the selected option's value ($period = \"30d\"). Pass that $variable into query arguments (live data), or key written-in data by it.",
  "DateRangeFilter": "DateRangeFilter(value: $binding<string>, options?: {value: string, label?: string}[], label?: string) — Dropdown of preset options (default 7d, 30d, 90d, 12m, ytd) and a calendar for a custom range; value takes the $variable that holds the selection: a preset key (\"30d\") or a custom range \"2026-10-01..2026-10-31\". For live data, pass that $variable into query arguments; with data written into the program, use PeriodPicker.",
  "MultiSelectFilter": "MultiSelectFilter(value: $binding<string[]>, options: {value: string, label?: string}[], label: string) — Dropdown with checkboxes. value takes the $variable that holds an array of the selected options' values ($plans = [], and [] means all). For live data, pass that $variable into query arguments; with data written into the program, use ChipFilter or SelectFilter.",
  "ChipFilter": "ChipFilter(value: $binding<string>, options: {value: string, label?: string}[], label?: string) — Pills for 2–6 segments; one is always selected. value takes the $variable that holds the selected option's value. In a FilterBar for a dashboard-wide segment, or in a Card's controls to switch that card's breakdown (leave label out there: the card title names it).",
  "SelectFilter": "SelectFilter(value: $binding<string>, options: {value: string, label?: string}[], label: string) — Dropdown for one value out of a longer list. value takes the $variable that holds the selected option's value. In a FilterBar for a dashboard-wide segment, or in a Card's controls to switch that card's breakdown.",
  "CompareToggle": "CompareToggle(label?: string, defaultOn?: boolean, value?: $binding<string>, options?: {value: string, label?: string}[]) — Add one only when some component is given previous values. Compare dropdown: None, or one of options (e.g. [{value: \"prev\", label: \"Previous 30 days\"}, {value: \"yoy\", label: \"Same 30 days last year\"}]). The choice overlays the previous data on every chart that has it (dashed lines, ghost bars, funnel markers) and names it in legends and deltas. Without options it is one choice named by label (default \"Previous period\"): CompareToggle(\"Previous week\", true). Starts at None; defaultOn starts on the first choice. value, the third argument, takes the $variable, and is only needed with options: it holds the chosen option's value, or \"off\" for None ($compare = \"off\"); key each chart's previous data by it (prev[$compare]), so each choice shows its own data.",
  "Section": "Section(title: string, rows: (Kpis | Row | Tabs | Drawer | SearchBox | Toggle | Slider | Markdown | Callout | Empty | Frame | AskAgent | Freshness | RefreshButton)[], description?: string) — A titled group of Kpis strips and Rows of Cards. Pass \"\" as title for the lead KPI section.",
  "Row": "Row(items: Card[], height?: 240 | 320 | 400 | 480 | 560 | 640) — Cards side by side on a 12-column grid; their widths add up to a full row. Every card in a row is the same height, one of 240, 320, 400, 480, 560 or 640 px, and its chart stretches to fill it. Leave height out and the row picks one from its content: 400 for charts, 560 for tables, GeoMap and Flow, 480 for PointMap and Cohorts, 320 for summaries (Stat, KeyValues, SegmentedBar).",
  "Kpis": "Kpis(items: Kpi[]) — A strip of Kpi tiles that lays itself out: up to 6 per row, wrapping into balanced rows when narrow. More than 6 render as compact items (value, then label and change) that wrap the same way; sparklines and hints are left out there. Tiles are equal width; just list them.",
  "Kpi": "Kpi(label: string, value?: number | string, format?: Format, previous?: number, goodWhen?: GoodWhen, hint?: string, chart?: Trend | Progress | Split | States, tone?: \"good\" | \"bad\" | \"warning\" | \"info\" | \"neutral\") — Stat tile, only inside Kpis. value is a number, shown with format and its change vs previous (the same measure one period earlier), or a short text such as a plan, status or version (no format or previous; tone colours its status dot). hint is a short subtitle such as \"Paid plans only\". chart is at most one of: Trend(weekly) for a sparkline, Progress(50000) for progress toward a target, Split([\"Web\", \"App\"], [310, 190]) for what a total is made of, States([\"good\", \"good\", \"warning\"]) for a status per period.",
  "Trend": "Trend(values: number[], previous?: number[]) — A Kpi's sparkline, 8–13 points. previous is the same points one period earlier, dashed while compare is on.",
  "Progress": "Progress(target: number) — A Kpi's progress toward target (a limit when its goodWhen is \"down\"). For one headline number; several targets in a card are Goals.",
  "Split": "Split(labels: string[], values: number[]) — What a Kpi's total is made of, up to 3 parts, one label and one value each. For totals only, never rates or averages; a card about composition is a SegmentedBar.",
  "States": "States(states: (\"good\" | \"warning\" | \"bad\" | null)[]) — A Kpi's status strip: one dot per period, null for no data.",
  "Card": "Card(title: string, content: (Stat | TimeSeries | SmallMultiples | Bars | Dumbbell | Distribution | Donut | Treemap | Waterfall | Intervals | StatusTimeline | Flow | Scatter | GeoMap | PointMap | Funnel | Cohorts | Heatmap | Table | Leaderboard | Goal | SegmentedBar | KeyValues | Drawer | SearchBox | Toggle | Slider | Markdown | Callout | Empty | Frame | AskAgent | Freshness | RefreshButton | RecordList | Badge | LinkOut)[], width?: Width, subtitle?: string, controls?: (ChipFilter | SelectFilter)[]) — content stacks top to bottom, usually [Stat?, one visual]. Default width \"half\". title says what is plotted; subtitle gives units, period or source (\"Weekly · USD\"). controls are this card's own switches, shown in its header: a ChipFilter or SelectFilter for what the card is broken down by or which metric it plots, e.g. Card(\"Top sources\", [Leaderboard(...)], \"half\", \"Visitors\", [ChipFilter($sourceBy, [{value: \"channel\", label: \"Channel\"}, {value: \"domain\", label: \"Domain\"}])]).",
  "Stat": "Stat(value?: number, format?: Format, previous?: number, goodWhen?: GoodWhen, label?: string) — Headline number at the top of a Card, with change vs previous.",
  "TimeSeries": "TimeSeries(labels: string[], series: Series[], type?: \"line\" | \"area\" | \"bar\", format?: Format, stacked?: boolean | \"percent\", references?: Reference[], goodWhen?: GoodWhen, markers?: Marker[], curve?: \"smooth\" | \"linear\" | \"step\", forecastFrom?: string) — A metric over time. type \"line\" (default) for rates, \"area\" for volumes (stacked for parts of a whole; stacked \"percent\" for each part's share over time), \"bar\" for counts per period. markers flag events on the time axis. curve \"step\" for values that change in steps (prices, limits, plan tiers). forecastFrom is the first projected label: from there the line is dashed and the region shaded.",
  "Series": "Series(name: string, values: number[], previous?: number[], mark?: \"line\" | \"area\" | \"bar\", lows?: number[], highs?: number[]) — One series; previous is the same points for the previous period. Use null for gaps. mark overrides the chart type to mix bars and a line in the same unit, e.g. Series(\"7-day average\", avg, null, \"line\"). lows/highs shade a band such as a 95% interval: Series(\"Lift\", lift, null, \"line\", lower, upper).",
  "Reference": "Reference(label: string, value: number, axis?: \"y\" | \"x\") — A target or SLO line: Reference(\"Target\", 99.5). axis \"x\" draws a vertical line (Scatter only), e.g. an average on the x measure.",
  "Marker": "Marker(label: string, at: string) — An event on a TimeSeries' time axis (a deploy, incident or launch) at one of its labels: Marker(\"Deploy v2.4\", \"Oct 12\").",
  "SmallMultiples": "SmallMultiples(labels: string[], series: Series[], type?: \"area\" | \"line\", format?: Format, columns?: number) — A grid of small charts, one per series, on one shared scale, for more than 8 series, or when lines would tangle. Same unit across panels; never use it to mix units. type \"area\" (default) or \"line\"; columns fixes the grid (default fits ~180px panels). A Series' previous draws the previous period as a grey dashed line in its panel while compare is on.",
  "Bars": "Bars(labels: string[], series: Series[], format?: Format, orientation?: \"horizontal\" | \"vertical\", stacked?: boolean | \"percent\", goodWhen?: GoodWhen, references?: Reference[], diverging?: string[]) — Values across categories. For periods such as weeks or months, use TimeSeries with type \"bar\". Horizontal (default) for long labels and rankings; vertical for short labels and ordered buckets (histograms). Several series group side by side, or stack (stacked \"percent\" for each part's share). references draw lines such as a 1.0x break-even. diverging [aboveLabel, belowLabel] colours one series by sign around zero, e.g. [\"Ahead of plan\", \"Behind plan\"].",
  "Dumbbell": "Dumbbell(labels: string[], before: number[], after: number[], format?: Format, beforeLabel?: string, afterLabel?: string, goodWhen?: GoodWhen) — Two values per category joined by a line (before and after, this year and last, two segments) so you see who moved and how far. Reads better than paired bars past a handful of categories.",
  "Distribution": "Distribution(labels: string[], mins: number[], q1s: number[], medians: number[], q3s: number[], maxes: number[], format?: Format) — Spread, not just the average: one box plot per category: whiskers min to max, box the middle 50% (q1 to q3), line the median. For latency, order value, session length, deal size.",
  "Donut": "Donut(labels: string[], values: number[], format?: Format, centerLabel?: string, previous?: number[]) — Part of a whole with the total as the headline, up to 8 parts; past 8, the smallest fold into Other. previous (last period's values, same order) adds each part's change in share, in points, to its tooltip while compare is on. For a compact strip, use SegmentedBar.",
  "SegmentedBar": "SegmentedBar(labels: string[], values: number[], format?: Format, previous?: number[]) — Part of a whole as one bar with a legend of values and shares; up to 8 parts. previous (last period's values, same order) adds each part's change in share, in points, to its tooltip while compare is on. Inside a headline tile, use a Kpi with a Split chart instead.",
  "Treemap": "Treemap(labels: string[], values: number[], format?: Format, previous?: number[], groups?: string[]) — Part to whole with many parts, or a hierarchy: area is size. groups (same length as labels) nests items under parents and colours by parent, e.g. category → product. Use Donut or SegmentedBar for ≤8 flat parts. previous (last period's values, same order) adds each item's change in share, in points, to its tooltip while compare is on.",
  "Waterfall": "Waterfall(labels: string[], values: number[], format?: Format, endLabel?: string, goodWhen?: GoodWhen, subtotals?: string[]) — How a total moved: the first value is the starting total, the rest are signed changes, the end total is computed. Increases and decreases wear the good/bad status colours; pass goodWhen \"down\" when a decrease is the good outcome (costs). E.g. Waterfall([\"Start MRR\", \"New\", \"Expansion\", \"Churn\"], [398200, 18400, 9100, -9300], \"currency-compact\", \"End MRR\"). subtotals names labels drawn as the running total at that point (their values are ignored; pass 0), for a P&L: Waterfall([\"Revenue\", \"Cost of sales\", \"Gross profit\", \"Operating costs\"], [820000, -310000, 0, -280000], \"currency-compact\", \"Operating profit\", \"up\", [\"Gross profit\"]).",
  "Intervals": "Intervals(labels: string[], estimates: number[], lows: number[], highs: number[], format?: Format, baseline?: number, baselineLabel?: string, goodWhen?: GoodWhen) — Estimates with confidence intervals (forest plot), e.g. experiment lift. An interval clear of the baseline (default 0) is a clear effect: green when better, red when worse, by goodWhen (default \"up\"; \"neutral\" colours both sides alike). Intervals that cross the baseline stay grey.",
  "StatusTimeline": "StatusTimeline(labels: string[], periods: string[], states: (\"good\" | \"warning\" | \"bad\" | null)[]) — Uptime per service over time: one strip per service, one cell per period. labels, periods and states have one entry per cell: its service, its period and its state, as query rows give them: StatusTimeline(s.rows.service, s.rows.day, s.rows.state). A state is \"good\" (up), \"warning\" (degraded) or \"bad\" (down), or null for no data; the legend names them Up, Degraded and Down.",
  "Flow": "Flow(from: string[], to: string[], values: number[], format?: Format, previous?: number[]) — Sankey of a quantity between stages. from, to and values have one entry per link, as query rows give them: Flow(f.rows.source, f.rows.target, f.rows.users), or written in: Flow([\"Paid search\", \"Signed up\"], [\"Signed up\", \"Activated\"], [1210, 640]). Name loss nodes \"Dropped\", \"Exited\" or \"Churned\" (drawn grey). Links only move forward: one that loops back to an earlier node isn't drawn. Keep to ~4 columns and ~15 nodes. previous (last period's volume, one per link) adds each link's and step's change to the tooltips while compare is on.",
  "Scatter": "Scatter(labels: string[], xs: number[], ys: number[], xLabel: string, yLabel: string, xFormat?: Format, yFormat?: Format, sizes?: number[], groups?: string[], references?: Reference[], sizeLabel?: string, quadrants?: string[]) — Two measures per item, one entry per item in labels, xs and ys: Scatter(c.rows.campaign, c.rows.spend, c.rows.roas, \"Spend\", \"ROAS\", \"currency-compact\", \"multiplier\"). sizes scales each dot by a third measure (sizeLabel names it, e.g. \"Signups\"); groups gives each item a group. Up to 8 groups, each with its own colour and shape; past eight, the smallest fold into Other. A point with a null x or y isn't drawn and is named under the chart. Up to 10 points label themselves. references draw targets or averages: Reference(\"Avg spend\", 12000, \"x\") is vertical, a y reference horizontal; together they split the plot into quadrants.",
  "GeoMap": "GeoMap(region: \"world\" | \"us\", labels: string[], values: number[], format?: Format, previous?: number[], goodWhen?: GoodWhen, limit?: number, view?: \"count\" | \"total\") — Choropleth with a ranked list of every region (limit keeps the top N). region \"world\" takes country names or ISO codes (\"DE\", \"GBR\"); \"us\" takes state names or codes (\"NY\"). A switch reads regions as counts or % of total (view \"total\" opens on shares); hovering the map or the list highlights the same region in both. Use width \"two-thirds\" or \"full\".",
  "PointMap": "PointMap(region: \"world\" | \"us\", labels: string[], lats: number[], lons: number[], values: number[], format?: Format, previous?: number[], goodWhen?: GoodWhen, groups?: string[], valueLabel?: string) — Values at places (stores, cities, offices, data centres) as circles sized by value (area, not radius) on a world or US map, with a ranked list beside it. lats/lons in degrees. previous adds each place's change, coloured by goodWhen. groups gives each place a type, drawn as its own colour and shape. valueLabel names the measure (\"Headcount\"). The 8 biggest places label themselves. For values by country or US state, use GeoMap; give it width two-thirds or full.",
  "Funnel": "Funnel(labels: string[], values: number[], format?: Format, previous?: number[], shape?: \"bars\" | \"funnel\", segments?: Series[], basis?: \"step\" | \"start\") — Ordered conversion steps, scaled to the first step, with step-to-step conversion and drop-off; the weakest step is flagged. A switch reads the rates step to step or from the start; basis \"start\" opens on the second. segments splits each step by plan, channel or cohort: Series(\"Enterprise\", [...]) per segment, one value per step, summing to values (up to 8); like stacked Bars, a split funnel doesn't draw previous. shape \"bars\" (default) lists the steps as rows; \"funnel\" draws a left-to-right funnel whose height follows each step (it falls back to bars when the card is too narrow, under about 100px per step).",
  "Cohorts": "Cohorts(cohorts: string[], periods: string[], values: number[], sizes?: number[], format?: Format, view?: \"percent\" | \"people\", showValues?: boolean) — Retention grid. cohorts, periods and values have one entry per cell: its cohort, its period and the % of that cohort active in it, as query rows give them: Cohorts(c.rows.cohort, c.rows.period, c.rows.retained, c.rows.cohort_size). sizes is the cohort's size, repeated on each of its cells. Leave out (or null) the periods a cohort has not reached. Periods start at \"Week 0\" or \"Month 0\". A Show switch in the header prints the cells as Percent or Count (people: size × rate), or nothing (None, the default); showValues true opens it on view (\"percent\" or \"people\").",
  "Heatmap": "Heatmap(rows: string[], columns: string[], values: number[], format?: Format, showValues?: boolean, midpoint?: number, view?: \"count\" | \"total\" | \"row\") — Magnitude across two categories (weekday × hour). rows, columns and values have one entry per cell: its row label, its column label and its value, as query rows give them: Heatmap(h.rows.day, h.rows.hour, h.rows.n). Rows and columns draw in order of first appearance; a cell left out or null is no data. A Show switch in the header prints the cells as Count, % of total or % of row (colouring by that reading), or nothing (None, the default); showValues true opens it on view (\"count\", \"total\" or \"row\"). midpoint switches to a two-pole diverging scale around it, for values with a direction (change, variance vs plan, correlation): 0 for change.",
  "Table": "Table(columns: Column[], pageSize?: number, totals?: boolean, search?: string, groupBy?: string) — Sortable, paged table (default pageSize 10). totals adds a totals row for Columns that set total. search is the text to keep matching rows for. groupBy names a column (usually a chip or badge column) to group rows under a heading with their count.",
  "Column": "Column(label: string, values: (string | number | null | number[] | string[])[], kind?: \"text\" | \"primary\" | \"number\" | \"bar\" | \"delta\" | \"badge\" | \"sparkline\" | \"chip\" | \"date\" | \"progress\" | \"states\" | \"link\" | \"person\", format?: Format, tones?: Record<string, \"good\" | \"bad\" | \"warning\" | \"info\" | \"neutral\">, goodWhen?: GoodWhen, total?: \"sum\" | \"average\") — kind: \"primary\" (bold first column), \"text\", \"number\", \"bar\" (number with inline bar), \"delta\" (signed change coloured by goodWhen), \"badge\" (tones maps statuses to good/bad/warning/info/neutral; plain categories stay neutral), \"sparkline\" (values are number arrays), \"chip\" (a category such as plan, channel or region as a neutral chip; an array gives several tags), \"date\" (\"2026-11-08\" shown as Nov 8), \"progress\" (0–100, a share of a goal with a bar to 100%), \"states\" (one status dot per period: arrays of \"good\" | \"warning\" | \"bad\" | null), \"link\" (a URL, shown without https:// and opened in a new tab), \"person\" (a name with an initials avatar, for owners and assignees). total (\"sum\" or \"average\") only for amounts that add up across rows: never unique counts, rates, shares or per-unit values like CAC. goodWhen only matters for kind \"delta\".",
  "Leaderboard": "Leaderboard(labels: string[], values: number[], format?: Format, previous?: number[], goodWhen?: GoodWhen, limit?: number) — Ranked list with inline bars and change vs previous: top channels, pages, campaigns. Shows every item, sorted; a long list scrolls inside the card. limit keeps only the top N.",
  "Goal": "Goal(label: string, value: number, target: number, format?: Format, pace?: number, goodWhen?: GoodWhen, previous?: number) — Progress toward a target. pace (0–1) is how far through the period we are; the bar marks ahead/behind pace. goodWhen \"down\" makes target a ceiling (churn ≤ 2%). The bar takes the state's colour; past its target or limit, a tick marks it and the overrun shows beyond, with the amount named. Stack several in one Card. previous is where it stood at the same point last period: a grey tick on the track while compare is on. For a single headline number with a target, use a Kpi with a Progress chart instead; Goal is for several targets stacked in one card.",
  "KeyValues": "KeyValues(rows: KeyValue[]) — Label/value fact rows: KeyValues([KeyValue(\"Trials\", 572, \"number\", 547), KeyValue(\"Owner\", \"Growth team\")]).",
  "KeyValue": "KeyValue(label: string, value: number | string, format?: Format, previous?: number, goodWhen?: GoodWhen) — One row of KeyValues: a number (with format and change vs previous) or a short text.",
  "Tabs": "Tabs(tabs: Tab[], value?: $binding<string>) — Several views in one Section, one shown at a time: Tabs([Tab(\"Overview\", [...]), Tab(\"Errors\", [...])], $tab). value takes a $variable holding the shown tab's label ($tab = \"Overview\"), so other components can read it; left out, the first tab shows first.",
  "Tab": "Tab(label: string, rows: (Kpis | Row | Drawer | SearchBox | Toggle | Slider | Markdown | Callout | Empty | Frame | AskAgent | Freshness | RefreshButton)[]) — One view of Tabs: its label, then what it shows, the same things a Section holds.",
  "Drawer": "Drawer(title: string, value: $binding<string | number | boolean>, content: (Stat | TimeSeries | SmallMultiples | Bars | Dumbbell | Distribution | Donut | Treemap | Waterfall | Intervals | StatusTimeline | Flow | Scatter | GeoMap | PointMap | Funnel | Cohorts | Heatmap | Table | Leaderboard | Goal | SegmentedBar | KeyValues | SearchBox | Toggle | Slider | Markdown | Callout | Empty | Frame | AskAgent | Freshness | RefreshButton | RecordList | Badge | LinkOut)[]) — A details panel shown while value, a $variable, holds something (usually the id a RecordList wrote); its close button clears it. content holds what a Card holds. Look the picked item up from the rows: picked = @First(@Filter(rows, \"id\", \"==\", $selected)), then Drawer(picked.title, $selected, [KeyValues([KeyValue(\"Owner\", picked.owner)])]).",
  "SearchBox": "SearchBox(value: $binding<string>, placeholder?: string) — Type to filter. value takes the $variable that holds the text ($q = \"\"); read it with @Filter(rows, \"title\", \"contains\", $q) or a Table's search argument. placeholder says what is searched.",
  "Toggle": "Toggle(value: $binding<boolean>, label: string) — An on/off view option, e.g. Toggle($failing, \"Only failing\") with $failing = false; read it in a ternary: $failing ? @Filter(rows, \"status\", \"==\", \"Failing\") : rows.",
  "Slider": "Slider(value: $binding<number>, label: string, min: number, max: number, step?: number) — A number the user drags, e.g. a threshold or \"top N\": Slider($top, \"Show top\", 3, 20) with $top = 5. step defaults to 1.",
  "Markdown": "Markdown(text: string) — Written explanation in Markdown between the charts: what the numbers mean, what changed, what to look at.",
  "Callout": "Callout(text: string, tone?: \"info\" | \"warning\" | \"error\" | \"success\", title?: string) — A highlighted note, e.g. Callout(\"Two regions report late; their numbers are a day old.\", \"warning\"). tone: \"info\" (default), \"warning\", \"error\" or \"success\".",
  "Empty": "Empty(title: string, reason?: string) — What to show when there is nothing to show, with the reason, e.g. Empty(\"No open incidents\", \"Nothing has failed in the last 24 hours.\").",
  "Frame": "Frame(title: string, html: string, data?: any, height?: number) — Free HTML, CSS and JS for what no component draws, in a sandboxed frame with no network: no outside scripts, styles, fonts or images (images only as data: URLs), no access to the page, and no way out: links and navigation inside it are blocked (put a LinkOut beside it). html is one string: use single quotes inside it for HTML attributes and JS strings. data is passed in: the frame's script reads window.frameData or listens for the \"framedata\" event (event.detail). Its CSS can use the dashboard's colours, which follow light and dark mode: var(--ink), var(--muted), var(--accent), var(--border), var(--surface). The frame fits its content's height; height (px, default 240) is the starting height.",
  "AskAgent": "AskAgent(label: string, message: string) — A button that asks the agent about what is on screen, e.g. AskAgent(\"Explain this spike\", \"Why did checkout errors rise on Tuesday?\"). Clicking sends message to the agent in this thread; it costs a model call, so offer it only for questions the page cannot answer itself.",
  "Freshness": "Freshness(source: string) — When a declared source last answered and how it refreshes, e.g. Freshness(\"orders\") shows \"Updated 2 minutes ago · refreshes itself\" or, for an agent source, \"· refresh asks the agent\".",
  "RefreshButton": "RefreshButton(label?: string, source?: string) — Refreshes data now. RefreshButton() re-runs every query; RefreshButton(\"Refresh incidents\", \"incidents\") only that source. A file, git or pull request source re-runs at once; an agent source instead asks the agent in this thread to get it again and store it (one model call).",
  "RecordList": "RecordList(records: Record[], selected?: $binding<string | number>, tones?: Record<string, \"neutral\" | \"good\" | \"bad\" | \"warning\" | \"info\">) — Items from a system (issues, incidents, orders): RecordList(@Each(rows, \"r\", Record(r.id, r.title, r.status, r.owner, r.age, r.link)), $selected, {\"Open\": \"warning\", \"Done\": \"good\"}). Picking an item writes its id to selected's $variable ($selected = null), and picking it again clears it; a Drawer reading $selected shows the details. tones colours each status like Column's tones.",
  "Badge": "Badge(text: string, tone?: \"neutral\" | \"good\" | \"bad\" | \"warning\" | \"info\") — A coloured status word, e.g. Badge(\"Critical\", \"bad\"). tone: \"neutral\" (default), \"good\", \"bad\", \"warning\" or \"info\".",
  "LinkOut": "LinkOut(label: string, url: string) — A link that opens url in the user's browser, e.g. the item in its home system. Only http and https addresses; any other is refused.",
  "Record": "Record(id: string | number, title: string, status?: string, owner?: string, age?: string, link?: string) — One item of a RecordList: id (what picking it writes), title, then optional status (a badge), owner, age (\"3d\", \"2 h ago\") and link (an http or https address of the item in its home system)."
};
export const THEME_TOKENS = ["sheenPeak","skelLineTone","skelBlockTone","page","surface","surfaceSubtle","border","borderStrong","ink","inkSecondary","inkMuted","grid","accent","accentInk","series1","series2","series3","series4","series5","series6","series7","series8","mutedMark","seq1","seq2","seq3","seq4","seq5","seq6","seq7","seq8","seq9","seqInk1","seqInk2","seqInk3","seqInk4","seqInk5","seqInk6","seqInk7","seqInk8","seqInk9","areaWash","areaDot","areaStackTop","areaStackBottom","areaStackTex","texTint","texInk","barInk","div1","div2","div3","div4","div5","div6","div7","div8","div9","divInk1","divInk2","divInk3","divInk4","divInk5","divInk6","divInk7","divInk8","divInk9","good","goodMark","bad","badMark","warning","warningSoft","warningMark","info","neutralSoft","mapLand","radius","radiusMd","radiusSm","spaceXs","spaceSm","spaceMd","spaceLg","spaceXl","space2xl","shadow","shadowPop"] as const;
